import {NEIGHBOR_ART} from './assets/neighborhood-atlas.js?v=0.13.3';
import {neighborObjective,STORY_NAMES,PIPES} from './neighborhood.js?v=0.13.3';
import {residents} from './residents.js?v=0.13.3';
import {ROOMS,DOORS,sceneOf} from './indoors.js?v=0.13.3';
import {REGIONS,nextExit,regionOf,regionForTarget} from './regions.js?v=0.13.3';
export function createNeighborhoodUI({getState,world,run,openModal,closeModal,button,mark,showJournal,canPay}){
 const s=getState,n=()=>s().neighborhood,actions=x=>`<div class="action-list">${x}</div>`;
 const panel=(title,body,kind='neighbors')=>openModal(kind,'',title,body);
 const clothImage=choice=>{const m=NEIGHBOR_ART['resident-home-props-v1'],box=m.sprites[0].frames[choice==='blue'?1:0].recommended_crop_xywh;return `<svg class="cloth-preview" viewBox="${box.join(' ')}" aria-hidden="true"><image href="${m.file}" width="1254" height="1254"/></svg>`;};
 const doIt=(label,type,payload,again,disabled='',small='')=>button(label,()=>{if(run(type,payload))again();},{primary:true,disabled,small});
 const track=id=>button('在地图上标记下一步',()=>{mark(id);closeModal();});
 const done=(id,text)=>`<p class="quote">${text}</p><p>${neighborObjective(s(),id).body}</p>`;
 function person(id){
  const p=residents(s()).find(q=>q.id===id);if(!p)return;
  const quotes={taoen:n().taoen===5?'原来饭菜不用吃凉的。下次你路过，记得提醒我放下扳手。':'他们说水槽修好了。可我总担心还有一处接头没看见，一回头，饭又凉了。',mila:n().mila===3?'你看，桌布铺开的时候，谁也没先问它新不新。':'怎么洗都有一点旧颜色。后来我想，那也许不是污渍，是我们还记得的日子。',lucy:n().lucy===3?s().weather==='rain'&&s().minute>=1080?'雨声一大，我就想再烤一炉。今天不烤了，陪我听一会儿吧。':'给别人留位置很容易。轮到自己坐下来，我居然有点不习惯。':'大家收摊的时候都有地方坐。我先把最后一盘面包收好，很快就来。'};
  panel(p.name+' · '+STORY_NAMES[id],()=>`<div class="town-conversation"><span class="town-person ${id}" aria-hidden="true"></span><p class="quote">“${quotes[id]}”</p></div><p>${neighborObjective(s(),id).body}</p>${s().archive?.reported?'<p class="quote">'+({taoen:'封存设备的复查日期，我已经记下了。这回先吃饭，再去检查。',mila:'岑禾的名字不用留在失踪那一栏了。我给她留了干净的外套。',lucy:'清单交齐了，人也到齐了。今晚给岑禾留一份热汤。'}[id])+'</p>':''}${actions(!s().town.flags.market?'<p>公共夜市开幕后，再来听听街坊的新故事。</p>':!n()[id]?doIt('听听'+p.name+'的心事','neighborTalk',{person:id},()=>{mark(id);person(id);}):id==='lucy'&&n().lucy===1&&n().restClue?doIt('约她收摊后歇一会儿','inviteLucyRest',{},()=>{mark(id);person(id);}):'')}${actions(track(id)+button('回头见',closeModal))}`,'townTalk');world.talkingTo=id;
 }
 function blueprint(){panel('陶恩的水槽图纸',()=>`<p class="quote">水从高处走，也要有人听低处。</p><div class="pipe-sequence"><span>① 水槽出水口</span><b>→</b><span>② 林间检修口</span><b>→</b><span>③ 果树末端</span></div><p>顺着水流检查三个接头，再回屋测试压力。每次检查体力1、5分钟；按错顺序不会消耗。</p>${actions(n().taoen===1?doIt('记下图纸，开始检修','readBlueprint',{},()=>{mark('taoen');blueprint();}):'')}${actions(track('taoen')+button('收好图纸',closeModal))}`);}
 function pipe(id){const i=PIPES.indexOf(id);panel(['水槽出水口','林间检修口','果树末端'][i],()=>`<p>${['铜接头很牢，水流没有岔开。','检修盖下传来轻轻的回声，水还在向果园流。','末端有一小片湿痕，需要回去测测压力。'][i]}</p><p>已检查 ${n().pipe}/3 · 请按图纸顺序继续。</p>${actions(doIt('检查这个接头','inspectPipe',{id},()=>{mark('taoen');pipe(id);},n().taoen!==2?'先读图纸':n().pipe!==i?n().pipe>i?'已经检查过':'先检查上一个接头':'','体力1 · 5分钟')+track('taoen')+button('继续走走',closeModal))}`);}
 function gauge(){panel('铜表上的指针',()=>`<p>把水槽的三个接头逐一检查过，再看压力表，才能分清是哪里漏了气。</p><p>${n().taoen>=3?'指针缓慢回落。问题在末端密封，与水源污染无关。':'三个接头：'+n().pipe+'/3'}</p>${actions(doIt('让水流过铜表','testPressure',{},()=>{mark('taoen');gauge();},n().taoen!==2||n().pipe!==3?'先完成三个接头检查':'','体力2 · 10分钟')+track('taoen')+button('放下铜表',closeModal))}`);}
 function bench(){panel('陶恩的修理工作台',()=>`<p>${n().taoen<5?'木板上留着扳手印，密封件要照着旧接头的尺寸做好。':'陶恩把改造图留在最上面：“能早点做完，就早点回去吃饭。”'}</p><p>木材 ${s().inventory.wood} · 石料 ${s().inventory.stone} · 松脂 ${s().inventory.resin}</p>${actions(n().taoen===3?doIt('做好密封件，完成检修','sealPipe',{},()=>{mark('taoen');bench();},canPay(s(),{need:{wood:2,resin:1},energy:3}),'木材2 · 松脂1 · 体力3 · 15分钟'):n().taoen===5&&!n().waterCan?doIt('改造宽口水壶','upgradeCan',{},bench,canPay(s(),{need:{wood:4,stone:2,resin:1},energy:5}),'木材4 · 石料2 · 松脂1 · 体力5 · 20分钟'):n().waterCan?'<p>✓ 宽口水壶已做好，在背包切换单格 / 2×2浇水。</p>':'<p>'+neighborObjective(s(),'taoen').body+'</p>')}${actions(track('taoen')+button('离开工作台',closeModal))}`);}
 function photo(){panel('旧照片里的桌布',()=>`<p class="quote">年轻的米菈坐在窗边，母亲在白布上画下绿枝。照片边角写着：“洗旧了也没关系，还能铺很久。”</p>${actions(doIt('记住绿枝的样子','readClothPhoto',{},photo,n().mila<1?'先和米菈聊聊':n().clothClue?'已经记下':'')+track('mila')+button('放回照片',closeModal))}`);}
 function cloth(){panel('给旧花纹留个位置',()=>`<p>米菈准备好了染料。保留旧绿枝纹，或染成雨后的蓝，都可以。铺好以后，也能回来免费改色。</p><div class="cloth-choices">${clothImage(n().clothChoice)}<p>目前选择：${n().clothChoice==='old'?'保留绿枝纹':n().clothChoice==='blue'?'雨后蓝':'尚未选择'}</p></div>${actions(['old','blue'].map(choice=>doIt(choice==='old'?'保留米白绿枝纹':'染成雨后蓝','chooseCloth',{choice},()=>{mark('mila');cloth();},!n().clothClue?'先看旧照片':'')).join('')+track('mila')+button('离开洗衣台',closeModal))}`);}
 function hallCloth(){panel('铺开，一起坐下',()=>`${done('mila',n().mila===3?'“不必洗得像新的一样。它在这里，就很好。”':'会馆的桌边还空着。把选好的桌布铺上去。')}${actions(doIt('铺好米菈的桌布','placeCloth',{},hallCloth,n().mila!==2?n().mila===3?'已经铺好':'先去洗衣屋选桌布':'')+track('mila')+button('回到会馆',closeModal))}`);}
 function guestbook(){panel('夜市最后一页',()=>`<p class="quote">“露西阿姨，你留给自己的那张椅子在哪？”</p><p>字写得歪歪扭扭，旁边画着一块最大的面包。也许可以把这页念给露西听。</p>${actions(doIt('记下这句留言','readGuestbook',{},guestbook,n().lucy!==1?'先听露西说说话':n().restClue?'已经记下':'')+track('lucy')+button('合上留言簿',closeModal))}`);}
 function tea(){panel('给朋友留的椅子',()=>{
  const evening=s().minute>=1080&&s().minute<1200,here=id=>residents(s()).some(p=>p.id===id&&p.scene==='hall'&&!p.moving);
  return `<p>18:00–20:00，街坊会陆续走进会馆。过了今晚也没关系，明天还是这张椅子。</p>${n().taoen===5?'<p class="quote">陶恩：“下回轮到我做饭。今天这份，终于是热的。”</p>':''}${n().lucy===3?'<p class="quote">露西摘下围裙，把苹果小酥饼的配方留在桌上：“这次，也给自己留一份。”</p>':''}${actions((n().taoen===4?doIt('请陶恩吃一顿热饭','taoenDinner',{},tea,!evening?'18:00–20:00再来':!here('taoen')?'陶恩还在路上':''):'')+(n().lucy===2?doIt('和露西坐一会儿','lucyRest',{},tea,!evening?'18:00–20:00再来':!here('lucy')?'露西还在路上':''):'')+(s().minute<1080?button('等到18:00',()=>{if(run('wait'))closeModal();}):'')+button('翻开人物故事',()=>showJournal('people'))+button('在会馆走走',closeModal))}`;
 });}
 function curtains(){panel('米菈留下的窗帘',()=>`<p>窗边可以挂米白绿枝纹，或雨后蓝。随时更换，不消耗材料。</p>${actions([['old','挂上米白绿枝窗帘'],['blue','挂上雨后蓝窗帘'],[null,'暂时收起窗帘']].map(([choice,label])=>doIt(label,'curtains',{choice},curtains)).join('')+button('看看其他纪念',()=>showJournal('people'))+button('回到屋里',closeModal))}`);}
 function go(id){const p=residents(s()).find(p=>p.id===id);if(!p)return;closeModal();const here=sceneOf(s());if(here===p.scene){world.go(world.spots().find(t=>t.id===p.spotId));return;}if(ROOMS[here]){world.go(ROOMS[here].spots[0]);return;}const region=ROOMS[p.scene]?.parent||p.scene;const t=regionOf(s())!==region?nextExit(regionOf(s()),region):world.spots().find(q=>q.id===(p.scene==='shop'?'lucy':DOORS[p.scene]?.id));if(t)world.go(t);}
 function routeLine(target){const p=residents(s()).find(p=>p.spotId===target),room=p&&ROOMS[p.scene]?p.scene:Object.keys(ROOMS).find(k=>ROOMS[k].spots.some(q=>q.id===target)),to=p?.scene||room||regionForTarget(target),here=sceneOf(s());if(!to)return '';if(here===to)return '就在这里，靠近目标或跟随金色标记。';if(ROOMS[here])return '下一步：先从屋内下方出门。';const region=ROOMS[to]?.parent||to;return region!==here?'下一步：'+(nextExit(here,region)?.name||'查看区域图')+'。':'下一步：进入'+ROOMS[to].name+'。';}
 function journalHTML(){return `<p>夜市之后，听听熟人的新心事。每条故事都没有期限，错过约定可以隔天再来。</p>${['taoen','mila','lucy'].map(id=>{const q=neighborObjective(s(),id),p=residents(s()).find(r=>r.id===id);return `<section class="neighbor-card"><div class="neighbor-heading"><span class="town-person ${id}" aria-hidden="true"></span><div><h3>${q.complete?'✓ ':''}${q.title}</h3><p>${p?p.name+' · '+p.place+(p.moving?' · 正在前往'+p.destination:p.working?' · 工作中':''):'暂在水渠调查中'}</p></div></div><p>${q.body}</p><p class="small-note">${routeLine(q.target)}</p>${actions(track(id)+(p?button('去找'+p.name,()=>go(id)):''))}</section>`;}).join('')}`;}
 function handle(t){
  const door=Object.keys(DOORS).find(k=>['repair','laundry'].includes(k)&&DOORS[k].id===t.id);if(door){panel(ROOMS[door].name,()=>`<p>${door==='repair'?'铜管与扳手沿墙摆开，炉边留着一张小床。':'洗好的布叠在架上，窗下的针线还没收起来。'}</p><p>${(()=>{const p=residents(s()).find(p=>p.id===(door==='repair'?'taoen':'mila'));return p?p.name+'现在在'+p.place+(p.moving?'，正在前往'+p.destination:'')+'。':'主人暂在水渠调查中，屋里的故事会等他回来。';})()}</p>${actions(button('推门进去',()=>{if(run('enterRoom',{room:door}))closeModal();},{primary:true})+button('先在广场走走',closeModal))}`);return true;}
  if(PIPES.includes(t.id)){pipe(t.id);return true;}
  if(t.id==='keepsake'&&n().mila===3){curtains();return true;}
  const handlers={repairBlueprint:blueprint,repairGauge:gauge,repairBench:bench,laundryPhoto:photo,laundryCloth:cloth,laundrySewing:()=>panel('窗边的针线',()=>`<p>米菈把线头卷得很整齐。她出门的时候，也会给针套上小布帽。</p>${actions(track('mila')+button('不动她的针线',closeModal))}`),hallCloth,marketGuestbook:guestbook,hallTea:tea};
  if(handlers[t.id]){handlers[t.id]();return true;}return false;
 }
 return {handle,person,journalHTML};
}
